--
-- Name: calcular_aprobacion_r3(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_aprobacion_r3(p_postulacion_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_votos_si INTEGER;
  v_total_votos INTEGER;
  v_aprobacion DECIMAL(5, 4);
BEGIN
  SELECT
    COUNT(CASE WHEN valor = 1 THEN 1 END),
    COUNT(*)
  INTO v_votos_si, v_total_votos
  FROM votaciones v
  JOIN rondas r ON r.id = v.ronda_id
  WHERE v.postulacion_id = p_postulacion_id
    AND r.numero = 3;

  IF v_total_votos = 0 THEN
    RETURN NULL;
  END IF;

  v_aprobacion := v_votos_si::DECIMAL / v_total_votos;
  RETURN v_aprobacion;
END;
$$;


--
-- Name: calcular_indice_r1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_indice_r1(p_postulacion_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_suma INTEGER;
  v_votos INTEGER;
  v_indice DECIMAL(5, 4);
BEGIN
  SELECT
    COALESCE(SUM(valor), 0),
    COUNT(*)
  INTO v_suma, v_votos
  FROM votaciones v
  JOIN rondas r ON r.id = v.ronda_id
  WHERE v.postulacion_id = p_postulacion_id
    AND r.numero = 1;

  IF v_votos = 0 THEN
    RETURN NULL;
  END IF;

  v_indice := v_suma::DECIMAL / (2.0 * v_votos);
  RETURN v_indice;
END;
$$;


--
-- Name: calcular_precios_obra(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_precios_obra() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Si hay precio_mxn (ganancia artista), calcular los demás precios
  IF NEW.precio_mxn IS NOT NULL AND NEW.precio_mxn > 0 THEN
    -- Precio público = ganancia / 0.75
    NEW.precio_publico := NEW.precio_mxn / 0.75;

    -- Comisión = precio público - ganancia
    NEW.comision_artefacto := NEW.precio_publico - NEW.precio_mxn;

    -- Precio sugerido = redondear precio público a la centena más cercana
    NEW.precio_sugerido := CEIL(NEW.precio_publico / 500) * 500;
  ELSE
    -- Si no hay precio, limpiar los campos calculados
    NEW.precio_publico := NULL;
    NEW.comision_artefacto := NULL;
    NEW.precio_sugerido := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: calcular_respaldo_r2(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calcular_respaldo_r2(p_postulacion_id integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_votos_artista INTEGER;
  v_total_curadores_votaron INTEGER;
  v_respaldo DECIMAL(5, 4);
BEGIN
  -- Curadores que votaron a este artista
  SELECT COUNT(DISTINCT curador_id)
  INTO v_votos_artista
  FROM votaciones v
  JOIN rondas r ON r.id = v.ronda_id
  WHERE v.postulacion_id = p_postulacion_id
    AND r.numero = 2
    AND v.valor = 1;

  -- Total de curadores que votaron en la ronda
  SELECT COUNT(DISTINCT v.curador_id)
  INTO v_total_curadores_votaron
  FROM votaciones v
  JOIN rondas r ON r.id = v.ronda_id
  JOIN postulaciones p ON p.id = v.postulacion_id
  WHERE p.id = p_postulacion_id
    AND r.numero = 2;

  IF v_total_curadores_votaron = 0 THEN
    RETURN NULL;
  END IF;

  v_respaldo := v_votos_artista::DECIMAL / v_total_curadores_votaron;
  RETURN v_respaldo;
END;
$$;


--
-- Name: generar_folio_artista(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generar_folio_artista() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  anio_actual INTEGER;
  contador INTEGER;
  nuevo_folio VARCHAR(20);
  max_intentos INTEGER := 10;
  intento INTEGER := 0;
BEGIN
  -- Obtener año actual
  anio_actual := EXTRACT(YEAR FROM CURRENT_DATE);

  -- Solo generar folio si no tiene uno
  IF NEW.folio IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Intentar generar folio único (con reintentos en caso de colisión)
  LOOP
    intento := intento + 1;

    -- Obtener siguiente número de la secuencia
    -- IMPORTANTE: Usamos nextval que es atómico y thread-safe
    EXECUTE format('SELECT nextval(''folio_%s_seq'')', anio_actual) INTO contador;

    -- Generar folio: ART-2026-001
    nuevo_folio := 'ART-' || anio_actual || '-' || LPAD(contador::TEXT, 3, '0');

    -- Verificar si ya existe (por si acaso)
    IF NOT EXISTS (SELECT 1 FROM artistas WHERE folio = nuevo_folio) THEN
      NEW.folio := nuevo_folio;
      RETURN NEW;
    END IF;

    -- Si llegamos aquí, el folio ya existe (muy raro)
    -- Reintentar con el siguiente número
    IF intento >= max_intentos THEN
      RAISE EXCEPTION 'No se pudo generar un folio único después de % intentos', max_intentos;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: reset_folio_sequence(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_folio_sequence(anio integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  max_numero INTEGER;
  sequence_name TEXT;
BEGIN
  sequence_name := 'folio_' || anio || '_seq';

  -- Buscar el número más alto ya usado ese año
  EXECUTE format(
    'SELECT COALESCE(MAX(CAST(SUBSTRING(folio FROM ''ART-%s-([0-9]+)'') AS INTEGER)), 0) FROM artistas WHERE folio LIKE ''ART-%s-%%''',
    anio, anio
  ) INTO max_numero;

  -- Crear secuencia si no existe
  EXECUTE format('CREATE SEQUENCE IF NOT EXISTS %I START 1', sequence_name);

  -- Resetear al siguiente número disponible
  EXECUTE format('SELECT setval(''%I'', %s)', sequence_name, max_numero + 1);

  RAISE NOTICE 'Secuencia % reseteada a %', sequence_name, max_numero + 1;
END;
$$;


