CREATE TABLE public.artistas (
    id integer NOT NULL,
    nombre character varying(255) NOT NULL,
    apellido character varying(255) NOT NULL,
    email character varying(255) NOT NULL,
    telefono character varying(50),
    fecha_nacimiento date,
    ciudad character varying(255),
    pais character varying(255),
    categoria character varying(100),
    bio text,
    foto text,
    instagram character varying(500),
    facebook character varying(500),
    website character varying(500),
    cv_url text,
    portfolio_url text,
    identificacion_url text,
    aprobado boolean DEFAULT false,
    estado_registro character varying(50) DEFAULT 'pendiente'::character varying,
    paquete_id integer,
    layout_canvas_url text,
    layout_canvas_data jsonb,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    nombre_artistico character varying(255),
    folio character varying(20),
    fecha_pre_registro timestamp without time zone,
    recordatorios_enviados integer DEFAULT 0,
    ultimo_recordatorio_enviado timestamp without time zone,
    fecha_registro_completo timestamp without time zone,
    token_acceso character varying(64) DEFAULT NULL::character varying,
    layout_canvas_pdf text,
    como_te_enteraste character varying(50),
    CONSTRAINT artistas_estado_registro_check CHECK (((estado_registro)::text = ANY ((ARRAY['pre_registrado'::character varying, 'pendiente'::character varying, 'aprobado'::character varying, 'rechazado'::character varying])::text[])))
);


