--
-- Name: v_postulaciones_metricas; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_postulaciones_metricas AS
 SELECT p.id,
    p.fase_origen_id,
    p.artista_id,
    p.disciplina,
    p.tipo,
    p.estado,
    p.fase_actual_id,
    p.es_carryover,
    p.indice_r1,
    p.respaldo_r2,
    p.aprobacion_r3,
    p.posicion,
    p.created_at,
    p.updated_at,
    a.nombre,
    a.apellido,
    a.email AS artista_email,
    a.foto AS artista_foto,
    f_origen.nombre AS fase_origen_nombre,
    f_actual.nombre AS fase_actual_nombre,
    public.calcular_indice_r1(p.id) AS indice_r1_calculado,
    ( SELECT count(*) AS count
           FROM (public.votaciones v
             JOIN public.rondas r ON ((r.id = v.ronda_id)))
          WHERE ((v.postulacion_id = p.id) AND (r.numero = 1))) AS total_votos_r1,
    public.calcular_respaldo_r2(p.id) AS respaldo_r2_calculado,
    ( SELECT count(*) AS count
           FROM (public.votaciones v
             JOIN public.rondas r ON ((r.id = v.ronda_id)))
          WHERE ((v.postulacion_id = p.id) AND (r.numero = 2))) AS total_votos_r2,
    public.calcular_aprobacion_r3(p.id) AS aprobacion_r3_calculado,
    ( SELECT count(*) AS count
           FROM (public.votaciones v
             JOIN public.rondas r ON ((r.id = v.ronda_id)))
          WHERE ((v.postulacion_id = p.id) AND (r.numero = 3))) AS total_votos_r3,
    ( SELECT count(*) AS count
           FROM public.obras
          WHERE (obras.postulacion_id = p.id)) AS total_obras
   FROM (((public.postulaciones p
     JOIN public.artistas a ON ((a.id = p.artista_id)))
     LEFT JOIN public.fases f_origen ON ((f_origen.id = p.fase_origen_id)))
     LEFT JOIN public.fases f_actual ON ((f_actual.id = p.fase_actual_id)));


